SELECT warehouse_id,count(*)::bigint AS positions,sum(physical)::bigint AS physical,sum(reserved)::bigint AS reserved,sum(CASE WHEN kind='storage' THEN physical-reserved ELSE 0 END)::bigint AS free_storage,sum(CASE WHEN kind='receiving' THEN physical ELSE 0 END)::bigint AS receiving,sum(CASE WHEN kind='staging' THEN physical ELSE 0 END)::bigint AS staged,bool_and(kind IS NOT NULL AND physical>=0 AND reserved>=0 AND reserved<=physical AND physical=ledger AND reserved=allocation_reserved) AS ok FROM wms_lot_trace_balances($1,$2,$3) GROUP BY warehouse_id
